@Component
class ProviderClient {

    private static final long FIRST_BACKOFF_MS = 100;

    private static final long MAX_BACKOFF_MS = 1_000;

    record Charge(String paymentId, String accountId, long amountMinor) {
    }

    private final RestClient http;

    private final JsonMapper json;

    private final boolean idempotencyKey;

    private final boolean backoff;

    ProviderClient(@Value("${payments.provider.url:}") String url, @Value("${payments.provider.timeout:1s}") Duration timeout, @Value("${payments.provider.idempotency-key:none}") String key, @Value("${payments.provider.retry:immediately}") String retry, JsonMapper json) {
        this.json = json;
        this.idempotencyKey = key.equals("payment-id");
        this.backoff = retry.equals("with-backoff");
        if (url.isBlank()) {
            this.http = null;
        } else {
            var factory = new JdkClientHttpRequestFactory(HttpClient.newBuilder().connectTimeout(timeout).build());
            factory.setReadTimeout(timeout);
            this.http = RestClient.builder().baseUrl(url).requestFactory(factory).build();
        }
    }

    void charge(PaymentEvent p) {
        if (http == null)
            return;
        String body = json.writeValueAsString(new Charge(p.paymentId(), p.accountId(), p.amountMinor()));
        for (int attempt = 1; ; attempt++) {
            if (Thread.currentThread().isInterrupted())
                throw new IllegalStateException("stopped while charging " + p.paymentId());
            try {
                var request = http.post().uri("/charges").contentType(MediaType.APPLICATION_JSON).body(body);
                if (idempotencyKey)
                    request = request.header("Idempotency-Key", p.paymentId());
                request.retrieve().toBodilessEntity();
                return;
            } catch (ResourceAccessException | HttpServerErrorException e) {
                if (backoff)
                    pause(attempt);
            }
        }
    }

    private static void pause(int attempt) {
        long ceiling = Math.min(MAX_BACKOFF_MS, FIRST_BACKOFF_MS << Math.min(attempt - 1, 10));
        try {
            Thread.sleep(ceiling / 2 + ThreadLocalRandom.current().nextLong(ceiling / 2 + 1));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

@Service
class PaymentService {

    enum Dedupe {

        NONE,
        CHECK_THEN_INSERT,
        CLAIM_FIRST
    }

    private final JdbcClient db;

    private final Dedupe dedupe;

    private final boolean byEventId;

    private final ProviderClient provider;

    private final MerchantBalance merchant;

    private final CompletedEvents completed;

    PaymentService(JdbcClient db, @Value("${payments.dedupe:none}") String dedupe, @Value("${payments.dedupe-key:event-id}") String key, ProviderClient provider, MerchantBalance merchant, CompletedEvents completed) {
        this.db = db;
        this.dedupe = Dedupe.valueOf(dedupe.toUpperCase(Locale.ROOT).replace('-', '_'));
        this.byEventId = key.equals("event-id");
        this.provider = provider;
        this.merchant = merchant;
        this.completed = completed;
    }

    @Transactional
    public void process(PaymentEvent p) {
        switch(dedupe) {
            case NONE ->
                apply(p);
            case CHECK_THEN_INSERT ->
                {
                    if (alreadyProcessed(p))
                        return;
                    apply(p);
                    markProcessed(p);
                }
            case CLAIM_FIRST ->
                {
                    if (markProcessed(p) == 0)
                        return;
                    apply(p);
                }
        }
    }

    void apply(PaymentEvent p) {
        provider.charge(p);
        db.sql("update accounts set balance_minor = balance_minor - ? where account_id = ?").params(p.amountMinor(), p.accountId()).update();
        merchant.credit(p.amountMinor());
        db.sql("insert into payments(payment_id, account_id, amount_minor) values (?, ?, ?)").params(p.paymentId(), p.accountId(), p.amountMinor()).update();
        completed.paymentApplied(p);
    }

    private boolean alreadyProcessed(PaymentEvent p) {
        return db.sql("select exists(select 1 from processed_events where payment_id = ?)").param(key(p)).query(Boolean.class).single();
    }

    private int markProcessed(PaymentEvent p) {
        return db.sql("insert into processed_events(payment_id) values (?) on conflict do nothing").param(key(p)).update();
    }

    private String key(PaymentEvent p) {
        return byEventId ? p.eventId() : p.paymentId();
    }
}
```

